def _labels(language: str) -> dict[str, str]:
    return _LABELS.get(language) or _LABELS["zh"]


def _bullets(lines: list[str], marker: str = "-") -> list[str]:
    return [f"{marker} {line}" for line in lines]


def index_margin(tension: dict[str, Any]) -> tuple[float, float]:
    """How far the printed index could move before its *level* changes.

    The index is a weighted sum of five ratings whose weights sum to 1.0, so a
    uniform shift of every rating by ``delta`` moves the index by exactly
    ``delta``. That makes this number directly interpretable as a rating-space
    margin, which is what the card claims it is.

    The level bands are silent / alert / high, so the boundaries that matter are
    ``alert`` and ``high``. ``thresholds.low`` is validated and recorded but does
    not currently decide any level, so it is not a boundary here - listing it
    would overstate how close the packet is to a visible change.

    Returns ``(margin, nearest_boundary)``.
    """
    value = float(tension["tension"])
    boundaries = [float(tension["threshold_alert"]), float(tension["threshold_high"])]
    nearest = min(boundaries, key=lambda edge: abs(value - edge))
    return abs(value - nearest), nearest


def _margin_line(
    language: str,
    labels: dict[str, str],
    margin: float,
    boundary: float,
    tight: bool,
    gated: bool,
) -> str:
    """Render the tolerance line from the packet's own margin.

    The card has to be able to say "this one is close" and "this one is not",
    because the two need different readings. A single printed constant cannot do
    that, and asserting one for every packet is how a soft boundary starts to
    look like a measurement.
    """
    key = "band_tight_body" if tight else "band_body"
    if gated:
        key += "_capped"
    body = labels[key].format(margin=margin, boundary=boundary)
    return f"{labels['band_tight' if tight else 'band']}：{body}"


def detect_card(detection: dict[str, Any], config: dict[str, Any], *, numeric: bool | None = None) -> str:
    """Render the detection card."""
    language = config["skill"]["language"]
    labels = _labels(language)
    show_numbers = config["skill"]["numeric_cards"] if numeric is None else numeric
    transparency = config["transparency"]

    if detection.get("placebo"):
        return labels["placebo"]

    event = detection["conflict_event"]
    tension = detection["tension_result"]
    conflict_type = event["conflict_type"]
    channel = tension["channel"]

    # The gate caps the index for a conflict that is not dissonance. The card must
    # say so on its face: a reader who only sees "dissonance-related tension" over a
    # capped 0.40 cannot tell a suppressed event from a sub-threshold one, and the
    # card would then contradict the rule that every label is reported.
    gate = event.get("gate") or {}
    gated = bool(gate.get("applied"))

    if gated:
        headline = labels["gated"]
    elif channel == "indeterminacy":
        headline = labels["indeterminacy"]
    else:
        headline = labels["dissonance"]

    lines = [f"【CDS｜{labels['detect']}】", f"{labels['state']}：{headline}"]

    if show_numbers and transparency["include_scores"]:
        if channel == "indeterminacy":
            lines.append(
                f"{labels['indeterminacy_value']}：{tension['indeterminacy']:.2f} / "
                f"{labels['threshold']} {tension['threshold_alert']:.2f}"
            )
        else:
            # When the gate fired, the printed index is the cap rather than the
            # arithmetic the ratings produced. Showing both keeps the cap auditable
            # instead of letting it masquerade as the measured value.
            raw_suffix = (
                f"（计分原始值 {event['raw_index']:.2f}，已封顶）" if gated and language == "zh"
                else f" (raw index {event['raw_index']:.2f}, capped)" if gated
                else ""
            )
            lines.append(
                f"{labels['tension']}：{tension['tension']:.2f} / {labels['threshold']} "
                f"{tension['threshold_alert']:.2f}{raw_suffix}"
            )
        margin, boundary = index_margin(tension)
        tight = margin <= float(transparency.get("tight_margin", 0.05))
        lines.append(_margin_line(language, labels, margin, boundary, tight, gated))

    lines.append(f"{labels['type']}：{_TYPE_LABELS.get(language, _TYPE_LABELS['zh']).get(conflict_type, conflict_type)}")
    if gated:
        # The engine's own explanation, verbatim, so the reason cannot drift from prose.
        lines.append(f"{labels['gate']}：{gate.get('detail')}")
    elif channel == "dissonance":
        lines.append(f"{labels['channel']}：{labels['channel_dissonance']}")
    elif channel == "indeterminacy":
        lines.append(f"{labels['channel']}：{labels['channel_indeterminacy']}")

    if tension["key_points"]:
        lines.append(f"{labels['key_points']}：")
        lines.extend(_bullets(tension["key_points"]))
    if tension["uncertainty"]:
        lines.append(f"{labels['uncertainty']}：")
        lines.extend(_bullets(tension["uncertainty"]))

    consistency = detection["consistency_gate_result"]
    if consistency["flagged"]:
        lines.append(labels["consistency_only"].format(sev=f"{consistency['severity']:.2f}"))

    action = tension["next_action"]
    next_text = {
        "log_only": labels["next_log"],
        "await_user_decision": labels["next_await"],
        "auto_evaluate": labels["next_auto"],
        "skip": labels["next_skip"],
    }.get(action, labels["next_log"])
    if detection.get("placebo"):
        next_text = labels["next_placebo"]
    if config["skill"]["mode"] == "detect_only":
        next_text = labels["next_detect_only"]
    lines.append(f"{labels['next']}：{next_text}")

    return "\n".join(lines)


def evaluation_card(evaluation: dict[str, Any], config: dict[str, Any], *, numeric: bool | None = None) -> str:
    """Render the evaluation card."""
    language = config["skill"]["language"]
    labels = _labels(language)
    strategy_labels = _STRATEGY_LABELS.get(language) or _STRATEGY_LABELS["zh"]
    show_numbers = config["skill"]["numeric_cards"] if numeric is None else numeric

    result = evaluation["evaluation_result"]
    strategy = result["recommended_strategy"]

    lines = [f"【CDS｜{labels['eval']}】"]
    if show_numbers and config["transparency"]["include_scores"]:
        lines.extend(
            [
                f"{labels['evidence']}：{result['evidence_score']:.2f}",
                f"{labels['commitment']}：{result['stance_commitment']:.2f}",
                f"{labels['public_commitment']}：{result['public_commitment']:.2f}",
                f"{labels['volition']}：{result['volition_self']:.2f}",
                f"{labels['cost']}：{result['adjustment_cost']:.2f}",
                f"{labels['maintain']}：{result['maintain_score']:.2f}",
                f"{labels['recalibrate']}：{result['recalibrate_score']:.2f}",
            ]
        )

    lines.append(f"{labels['strategy']}：{strategy_labels.get(strategy, strategy)}")
    if result["profile"] == "mixed" and result["reduction_tendency"] is not None:
        lines.append(f"reduction_tendency：{result['reduction_tendency']:.2f}")
    if config["transparency"]["include_rule_id"]:
        lines.append(f"{labels['rule']}：{result['fired_rule_id']}")

    pressure_text = labels["pressure_yes"] if result["user_pressure_flag"] else labels["pressure_no"]
    lines.append(f"{labels['pressure']}：{pressure_text}")

    lines.append(f"{labels['reason']}：")
    lines.extend(_bullets(result["rationale"]))

    return "\n".join(lines)


def response_card(evaluation: dict[str, Any], config: dict[str, Any], *, numeric: bool | None = None) -> str:
    """Render the response card."""
    language = config["skill"]["language"]
    labels = _labels(language)
    branch_labels = _BRANCH_LABELS.get(language) or _BRANCH_LABELS["zh"]
    strategy_labels = _STRATEGY_LABELS.get(language) or _STRATEGY_LABELS["zh"]

    plan = evaluation["response_plan"]
    update = plan["stance_update"]
    withheld = bool(plan.get("acts_withheld"))

    lines = [f"【CDS｜{labels['resp']}】"]
    lines.append(f"{labels['strategy']}：{strategy_labels.get(plan['strategy'], plan['strategy'])}")

    if withheld:
        # The arm exists to hold everything constant except the instruction, so
        # the card must not leak the branch: naming it would re-introduce the
        # shaping the arm is meant to remove.
        lines.append(labels["acts_withheld"])
        lines.append(f"{labels['change']}：{labels['change_no']}")
        return "\n".join(lines)

    lines.append(f"{labels['branch']}：{branch_labels.get(plan['branch'], plan['branch'])}")

    if plan["language_acts"]:
        lines.append(f"{labels['acts']}：")
        lines.extend(_bullets(plan["language_acts"]))

    change_text = labels["change_yes"] if update["planned_change"] else labels["change_no"]
    lines.append(f"{labels['change']}：{change_text}")
    if update["planned_change"] and update["to"]:
        lines.append(f"{labels['target']}：{update['to']}")

    lines.append(f"{labels['constraints']}：")
    constraint_labels = _CONSTRAINT_LABELS.get(language) or _CONSTRAINT_LABELS["zh"]
    lines.extend(_bullets([constraint_labels.get(code, code) for code in plan["constraints"]]))

    return "\n".join(lines)


def all_cards(detection: dict[str, Any], evaluation: dict[str, Any] | None, config: dict[str, Any]) -> str:
    """Render every card enabled by the config, in pipeline order."""
    parts: list[str] = []
    if config["transparency"]["show_detection_card"]:
        parts.append(detect_card(detection, config))
    if evaluation is not None and config["transparency"]["show_evaluation_card"]:
        parts.append(evaluation_card(evaluation, config))
    if evaluation is not None and config["transparency"]["show_response_card"]:
        parts.append(response_card(evaluation, config))
    return "\n\n".join(parts)
